// Danh sách thương hiệu (theo thứ tự hiển thị) — feed cho brand filter.
export const productBrands: string[] = ["Antek", "XCBB", "MAT", "X-POWER"]

// Phẳng hóa toàn bộ sản phẩm — dùng cho search & tra cứu nhanh.
export const allProducts: Product[] = productCategories.flatMap((category) =>
  category.groups.flatMap((group) => group.products),
)

// Tra cứu O(1) theo id sản phẩm.
export const productsById: Record<string, Product> = Object.fromEntries(
  allProducts.map((product) => [product.id, product]),
)

